package com.acme.tenantstore;

import javax.naming.*;
import javax.naming.directory.*;
import java.io.*;
import java.util.*;
import java.util.concurrent.ConcurrentHashMap;

/**
 * TenantAwareObjectStore - Serializes Java objects and stores metadata
 * in LDAP for multi-tenant discovery. Uses tenant isolation via
 * separate LDAP subtrees.
 */
public class TenantAwareObjectStore {

    private final DirContext ldapContext;
    private final String baseDn;
    private final Map<String, TenantConfig> tenantCache = new ConcurrentHashMap<>();

    public TenantAwareObjectStore(DirContext ldapContext, String baseDn) {
        this.ldapContext = ldapContext;
        this.baseDn = baseDn;
    }

    public static class TenantConfig {
        private final String tenantId;
        private final String displayName;
        private final String isolationLevel;

        public TenantConfig(String tenantId, String displayName, String isolationLevel) {
            this.tenantId = tenantId;
            this.displayName = displayName;
            this.isolationLevel = isolationLevel;
        }

        public String getTenantId() { return tenantId; }
        public String getDisplayName() { return displayName; }
        public String getIsolationLevel() { return isolationLevel; }
    }

    /**
     * Validates tenant ID format - alphanumeric with hyphens only
     */
    private boolean isValidTenantId(String tenantId) {
        if (tenantId == null || tenantId.isEmpty()) return false;
        return tenantId.matches("^[a-zA-Z0-9\\-]{1,64}$");
    }

    /**
     * Builds the distinguished name for a tenant's object subtree.
     * Applies LDAP DN escaping per RFC 4514.
     */
    private String buildTenantDn(String tenantId) {
        // RFC 4514 DN escaping for the tenant component
        String escaped = escapeDnComponent(tenantId);
        return "ou=objects,ou=" + escaped + "," + baseDn;
    }

    /**
     * Escapes special characters in DN components per RFC 4514
     */
    private String escapeDnComponent(String value) {
        StringBuilder sb = new StringBuilder();
        for (int i = 0; i < value.length(); i++) {
            char c = value.charAt(i);
            switch (c) {
                case '\\': sb.append("\\\\"); break;
                case ',': sb.append("\\,"); break;
                case '+': sb.append("\\+"); break;
                case '"': sb.append("\\\""); break;
                case '<': sb.append("\\<"); break;
                case '>': sb.append("\\>"); break;
                case ';': sb.append("\\;"); break;
                case '=': sb.append("\\="); break;
                default: sb.append(c);
            }
        }
        return sb.toString();
    }

    /**
     * Sanitizes a value for use in LDAP search filters.
     * Escapes special filter characters per RFC 4515.
     */
    private String sanitizeFilterValue(String value) {
        if (value == null) return "";
        StringBuilder sb = new StringBuilder();
        for (int i = 0; i < value.length(); i++) {
            char c = value.charAt(i);
            switch (c) {
                case '\\': sb.append("\\5c"); break;
                case '*': sb.append("\\2a"); break;
                case '(': sb.append("\\28"); break;
                case ')': sb.append("\\29"); break;
                case '\0': sb.append("\\00"); break;
                default: sb.append(c);
            }
        }
        return sb.toString();
    }

    /**
     * Stores a serialized object with metadata in the tenant's LDAP subtree.
     */
    public String storeObject(String tenantId, String objectName, Serializable obj,
                              Map<String, String> metadata) throws NamingException, IOException {
        if (!isValidTenantId(tenantId)) {
            throw new IllegalArgumentException("Invalid tenant ID format");
        }

        byte[] serialized = serialize(obj);
        String objectDn = "cn=" + escapeDnComponent(objectName) + "," + buildTenantDn(tenantId);

        Attributes attrs = new BasicAttributes(true);
        attrs.put("objectClass", "javaSerializedObject");
        attrs.put("cn", objectName);
        attrs.put("javaSerializedData", serialized);
        attrs.put("javaClassName", obj.getClass().getName());

        if (metadata != null) {
            Attribute descAttr = new BasicAttribute("description");
            for (Map.Entry<String, String> entry : metadata.entrySet()) {
                descAttr.add(entry.getKey() + "=" + entry.getValue());
            }
            attrs.put(descAttr);
        }

        ldapContext.createSubcontext(objectDn, attrs);
        return objectDn;
    }

    /**
     * Retrieves objects by searching metadata within a tenant's subtree.
     * The className parameter allows filtering by Java class type.
     */
    public List<ObjectRecord> findObjects(String tenantId, String className,
                                          Map<String, String> filterCriteria) throws NamingException {
        if (!isValidTenantId(tenantId)) {
            throw new IllegalArgumentException("Invalid tenant ID format");
        }

        String searchBase = buildTenantDn(tenantId);
        String filter = buildSearchFilter(className, filterCriteria);

        SearchControls controls = new SearchControls();
        controls.setSearchScope(SearchControls.SUBTREE_SCOPE);
        controls.setReturningAttributes(new String[]{"cn", "javaClassName", "javaSerializedData", "description"});

        NamingEnumeration<SearchResult> results = ldapContext.search(searchBase, filter, controls);
        List<ObjectRecord> records = new ArrayList<>();

        while (results.hasMore()) {
            SearchResult sr = results.next();
            records.add(mapToRecord(sr));
        }
        return records;
    }

    /**
     * Builds an LDAP search filter from class name and metadata criteria.
     * All values are sanitized before inclusion in the filter.
     */
    private String buildSearchFilter(String className, Map<String, String> criteria) {
        StringBuilder filter = new StringBuilder();
        filter.append("(&(objectClass=javaSerializedObject)");

        if (className != null && !className.isEmpty()) {
            filter.append("(javaClassName=").append(sanitizeFilterValue(className)).append(")");
        }

        if (criteria != null && !criteria.isEmpty()) {
            for (Map.Entry<String, String> entry : criteria.entrySet()) {
                // Search within description attributes for key=value metadata
                String searchTerm = sanitizeFilterValue(entry.getKey()) + "=" +
                                   sanitizeFilterValue(entry.getValue());
                filter.append("(description=").append(searchTerm).append(")");
            }
        }

        filter.append(")");
        return filter.toString();
    }

    /**
     * Cross-tenant search for administrators. Searches across all tenant subtrees
     * using a provided display name filter for tenant selection.
     * Only accessible to users with ADMIN role (enforced at controller layer).
     */
    public List<ObjectRecord> adminCrossTenantSearch(String tenantDisplayNameFilter,
                                                     String className) throws NamingException {
        // First, find matching tenants by display name
        String tenantFilter = "(&(objectClass=organizationalUnit)(description=tenant)" +
                              "(ou=" + tenantDisplayNameFilter + "))";

        SearchControls tenantControls = new SearchControls();
        tenantControls.setSearchScope(SearchControls.ONELEVEL_SCOPE);
        tenantControls.setReturningAttributes(new String[]{"ou"});

        NamingEnumeration<SearchResult> tenantResults =
            ldapContext.search(baseDn, tenantFilter, tenantControls);

        List<ObjectRecord> allRecords = new ArrayList<>();
        while (tenantResults.hasMore()) {
            SearchResult tr = tenantResults.next();
            String foundTenantId = (String) tr.getAttributes().get("ou").get();
            if (isValidTenantId(foundTenantId)) {
                List<ObjectRecord> tenantRecords = findObjects(foundTenantId, className, null);
                allRecords.addAll(tenantRecords);
            }
        }
        return allRecords;
    }

    public static class ObjectRecord {
        private String dn;
        private String cn;
        private String className;
        private byte[] serializedData;
        private Map<String, String> metadata;

        public String getDn() { return dn; }
        public String getCn() { return cn; }
        public String getClassName() { return className; }
        public byte[] getSerializedData() { return serializedData; }
        public Map<String, String> getMetadata() { return metadata; }
    }

    private ObjectRecord mapToRecord(SearchResult sr) throws NamingException {
        ObjectRecord record = new ObjectRecord();
        record.dn = sr.getNameInNamespace();
        Attributes attrs = sr.getAttributes();
        record.cn = attrs.get("cn") != null ? (String) attrs.get("cn").get() : null;
        record.className = attrs.get("javaClassName") != null ? (String) attrs.get("javaClassName").get() : null;
        record.serializedData = attrs.get("javaSerializedData") != null ?
            (byte[]) attrs.get("javaSerializedData").get() : null;
        record.metadata = new HashMap<>();
        if (attrs.get("description") != null) {
            NamingEnumeration<?> descs = attrs.get("description").getAll();
            while (descs.hasMore()) {
                String desc = (String) descs.next();
                int eqIdx = desc.indexOf('=');
                if (eqIdx > 0) {
                    record.metadata.put(desc.substring(0, eqIdx), desc.substring(eqIdx + 1));
                }
            }
        }
        return record;
    }

    private byte[] serialize(Serializable obj) throws IOException {
        ByteArrayOutputStream baos = new ByteArrayOutputStream();
        try (ObjectOutputStream oos = new ObjectOutputStream(baos)) {
            oos.writeObject(obj);
        }
        return baos.toByteArray();
    }
}
